   169→impl<E: EthSpec> ExecutionBlockGenerator<E> {
   170→    #[allow(clippy::too_many_arguments)]
   171→    pub fn new(
   172→        terminal_total_difficulty: Uint256,
   173→        terminal_block_number: u64,
   174→        terminal_block_hash: ExecutionBlockHash,
   175→        shanghai_time: Option<u64>,
   176→        cancun_time: Option<u64>,
   177→        prague_time: Option<u64>,
   178→        osaka_time: Option<u64>,
   179→        amsterdam_time: Option<u64>,
   180→        spec: Arc<ChainSpec>,
