   295→    pub fn move_to_block_prior_to_terminal_block(&mut self) -> Result<(), String> {
   296→        let target_block = self
   297→            .terminal_block_number
   298→            .checked_sub(1)
   299→            .ok_or("terminal pow block is 0")?;
   300→        self.move_to_pow_block(target_block)
   301→    }
   302→
   303→    pub fn move_to_terminal_block(&mut self) -> Result<(), String> {
   304→        self.move_to_pow_block(self.terminal_block_number)
   305→    }
   306→
   307→    pub fn move_to_pow_block(&mut self, target_block: u64) -> Result<(), String> {
   308→        let next_block = self.latest_block().unwrap().block_number() + 1;
   309→        assert!(target_block >= next_block);
   310→
   311→        self.insert_pow_blocks(next_block..=target_block)
   312→    }
   313→
   314→    pub fn drop_all_blocks(&mut self) {
   315→        self.blocks = <_>::default();
   316→        self.block_hashes = <_>::default();
   317→    }
   318→
   319→    pub fn insert_pow_blocks(
   320→        &mut self,
   321→        block_numbers: impl Iterator<Item = u64>,
   322→    ) -> Result<(), String> {
   323→        for i in block_numbers {
   324→            self.insert_pow_block(i)?;
   325→        }
   326→
   327→        Ok(())
   328→    }
