   330→    pub fn set_min_blob_count(&mut self, count: usize) {
   331→        self.min_blobs_count = count;
   332→    }
   333→
   334→    pub fn insert_pow_block(&mut self, block_number: u64) -> Result<(), String> {
   335→        if let Some(finalized_block_hash) = self.finalized_block_hash {
   336→            return Err(format!(
   337→                "terminal block {} has been finalized. PoW chain has stopped building",
   338→                finalized_block_hash
   339→            ));
   340→        }
   341→        let block = if block_number == 0 {
   342→            generate_genesis_block(self.terminal_total_difficulty, self.terminal_block_number)?
   343→        } else if let Some(block) = self.block_by_number(block_number - 1) {
   344→            generate_pow_block(
   345→                self.terminal_total_difficulty,
   346→                self.terminal_block_number,
   347→                block_number,
   348→                block.block_hash(),
   349→            )?
   350→        } else {
   351→            return Err(format!(
   352→                "parent with block number {} not found",
   353→                block_number - 1
   354→            ));
   355→        };
   356→
   357→        // Insert block into block tree
   358→        self.insert_block(Block::PoW(block))?;
   359→
   360→        // Set head
   361→        if let Some(head_total_difficulty) =
   362→            self.head_block.as_ref().and_then(|b| b.total_difficulty())
   363→        {
   364→            if block.total_difficulty >= head_total_difficulty {
   365→                self.head_block = Some(Block::PoW(block));
   366→            }
   367→        } else {
   368→            self.head_block = Some(Block::PoW(block));
   369→        }
   370→        Ok(())
   371→    }
   372→
   373→    /// Insert a PoW block given the parent hash.
   374→    ///
   375→    /// Returns `Ok(hash)` of the inserted block.
   376→    /// Returns an error if the `parent_hash` does not exist in the block tree or
   377→    /// if the parent block is the terminal block.
   378→    pub fn insert_pow_block_by_hash(
   379→        &mut self,
   380→        parent_hash: ExecutionBlockHash,
   381→        unique_id: u64,
   382→    ) -> Result<ExecutionBlockHash, String> {
   383→        let parent_block = self.block_by_hash(parent_hash).ok_or_else(|| {
   384→            format!(
   385→                "Block corresponding to parent hash does not exist: {}",
   386→                parent_hash
   387→            )
   388→        })?;
   389→
   390→        let mut block = generate_pow_block(
   391→            self.terminal_total_difficulty,
   392→            self.terminal_block_number,
   393→            parent_block.block_number() + 1,
   394→            parent_hash,
   395→        )?;
   396→
   397→        // Hack the block hash to make this block distinct from any other block with a different
   398→        // `unique_id` (the default is 0).
   399→        block.block_hash = ExecutionBlockHash::from_root(Hash256::from_low_u64_be(unique_id));
   400→        block.block_hash = ExecutionBlockHash::from_root(block.tree_hash_root());
   401→
   402→        let hash = self.insert_block(Block::PoW(block))?;
   403→
   404→        // Set head
   405→        if let Some(head_total_difficulty) =
   406→            self.head_block.as_ref().and_then(|b| b.total_difficulty())
   407→        {
   408→            if block.total_difficulty >= head_total_difficulty {
   409→                self.head_block = Some(Block::PoW(block));
   410→            }
   411→        } else {
   412→            self.head_block = Some(Block::PoW(block));
   413→        }
   414→        Ok(hash)
   415→    }
   416→
   417→    // This does not reject duplicate blocks inserted. This lets us re-use the same execution
   418→    // block generator for multiple beacon chains which is useful in testing.
   419→    pub fn insert_block(&mut self, block: Block<E>) -> Result<ExecutionBlockHash, String> {
   420→        if block.parent_hash() != ExecutionBlockHash::zero()
   421→            && !self.blocks.contains_key(&block.parent_hash())
   422→        {
   423→            return Err(format!("parent block {:?} is unknown", block.parent_hash()));
   424→        }
   425→
   426→        Ok(self.insert_block_without_checks(block))
   427→    }
   428→
   429→    pub fn insert_block_without_checks(&mut self, block: Block<E>) -> ExecutionBlockHash {
   430→        let block_hash = block.block_hash();
   431→        self.block_hashes
   432→            .entry(block.block_number())
   433→            .or_default()
   434→            .push(block_hash);
   435→        self.blocks.insert(block_hash, block);
   436→
   437→        block_hash
   438→    }
   439→
   440→    pub fn modify_last_block(&mut self, block_modifier: impl FnOnce(&mut Block<E>)) {
   441→        if let Some(last_block_hash) = self
   442→            .block_hashes
   443→            .iter_mut()
   444→            .max_by_key(|(block_number, _)| *block_number)
   445→            .and_then(|(_, block_hashes)| {
   446→                // Remove block hash, we will re-insert with the new block hash after modifying it.
   447→                block_hashes.pop()
   448→            })
   449→        {
   450→            let mut block = self.blocks.remove(&last_block_hash).unwrap();
   451→            block_modifier(&mut block);
   452→
   453→            // Update the block hash after modifying the block
   454→            match &mut block {
   455→                Block::PoW(b) => b.block_hash = ExecutionBlockHash::from_root(b.tree_hash_root()),
   456→                Block::PoS(b) => {
   457→                    *b.block_hash_mut() = ExecutionBlockHash::from_root(b.tree_hash_root())
   458→                }
   459→            }
   460→
   461→            // Update head.
   462→            if self
   463→                .head_block
   464→                .as_ref()
   465→                .is_none_or(|head| head.block_hash() == last_block_hash)
   466→            {
   467→                self.head_block = Some(block.clone());
   468→            }
   469→
   470→            self.insert_block_without_checks(block);
   471→        }
   472→    }
   473→
   474→    pub fn get_payload(&mut self, id: &PayloadId) -> Option<ExecutionPayload<E>> {
   475→        self.payload_ids.get(id).cloned()
   476→    }
   477→
   478→    pub fn get_blobs_bundle(&mut self, id: &PayloadId) -> Option<BlobsBundle<E>> {
   479→        self.blobs_bundles.get(id).cloned()
   480→    }
   481→
   482→    pub fn new_payload(&mut self, payload: ExecutionPayload<E>) -> PayloadStatusV1 {
   483→        let Some(parent) = self.blocks.get(&payload.parent_hash()) else {
   484→            return PayloadStatusV1 {
   485→                status: PayloadStatusV1Status::Syncing,
   486→                latest_valid_hash: None,
   487→                validation_error: None,
   488→            };
   489→        };
   490→
   491→        if payload.block_number() != parent.block_number() + 1 {
   492→            return PayloadStatusV1 {
   493→                status: PayloadStatusV1Status::Invalid,
   494→                latest_valid_hash: Some(parent.block_hash()),
   495→                validation_error: Some("invalid block number".to_string()),
   496→            };
   497→        }
   498→
   499→        let valid_hash = payload.block_hash();
   500→        self.pending_payloads.insert(payload.block_hash(), payload);
   501→
   502→        PayloadStatusV1 {
   503→            status: PayloadStatusV1Status::Valid,
   504→            latest_valid_hash: Some(valid_hash),
   505→            validation_error: None,
   506→        }
   507→    }
   508→
   509→    // This function expects payload_attributes to already be validated with respect to
   510→    // the current fork [obtained by self.get_fork_at_timestamp(payload_attributes.timestamp)]
   511→    pub fn forkchoice_updated(
   512→        &mut self,
   513→        forkchoice_state: ForkchoiceState,
   514→        payload_attributes: Option<PayloadAttributes>,
   515→    ) -> Result<JsonForkchoiceUpdatedV1Response, String> {
   516→        // This is meant to cover starting post-merge transition at genesis. Useful for
   517→        // testing Capella forks and later.
   518→        let head_block_hash = forkchoice_state.head_block_hash;
   519→        if let Some(genesis_pow_block) = self.block_by_number(0)
   520→            && genesis_pow_block.block_hash() == head_block_hash
   521→        {
   522→            self.terminal_block_hash = head_block_hash;
   523→        }
   524→
   525→        if let Some(payload) = self.pending_payloads.remove(&head_block_hash) {
   526→            self.insert_block(Block::PoS(payload))?;
   527→        }
   528→
   529→        let unknown_head_block_hash = !self.blocks.contains_key(&head_block_hash);
   530→        let unknown_safe_block_hash = forkchoice_state.safe_block_hash
   531→            != ExecutionBlockHash::zero()
   532→            && !self.blocks.contains_key(&forkchoice_state.safe_block_hash);
   533→        let unknown_finalized_block_hash = forkchoice_state.finalized_block_hash
   534→            != ExecutionBlockHash::zero()
   535→            && !self
   536→                .blocks
   537→                .contains_key(&forkchoice_state.finalized_block_hash);
   538→
   539→        if unknown_head_block_hash || unknown_safe_block_hash || unknown_finalized_block_hash {
   540→            return Ok(JsonForkchoiceUpdatedV1Response {
   541→                payload_status: JsonPayloadStatusV1 {
   542→                    status: JsonPayloadStatusV1Status::Syncing,
   543→                    latest_valid_hash: None,
   544→                    validation_error: None,
   545→                },
   546→                payload_id: None,
   547→            });
   548→        }
   549→
   550→        let id = match payload_attributes {
   551→            None => None,
   552→            Some(attributes) => {
   553→                let parent = self
   554→                    .blocks
   555→                    .get(&head_block_hash)
   556→                    .cloned()
   557→                    .ok_or_else(|| format!("unknown parent block {head_block_hash:?}"))?;
   558→
   559→                let id = payload_id_from_u64(self.next_payload_id);
   560→                self.next_payload_id += 1;
   561→
   562→                let execution_payload =
   563→                    self.build_new_execution_payload(head_block_hash, &parent, id, &attributes)?;
   564→
   565→                self.payload_ids.insert(id, execution_payload);
   566→
   567→                Some(id)
   568→            }
   569→        };
   570→
   571→        self.head_block = Some(
   572→            self.blocks
   573→                .get(&forkchoice_state.head_block_hash)
   574→                .unwrap()
   575→                .clone(),
   576→        );
   577→
   578→        if forkchoice_state.finalized_block_hash != ExecutionBlockHash::zero() {
   579→            self.finalized_block_hash = Some(forkchoice_state.finalized_block_hash);
   580→        }
   581→
   582→        Ok(JsonForkchoiceUpdatedV1Response {
   583→            payload_status: JsonPayloadStatusV1 {
   584→                status: JsonPayloadStatusV1Status::Valid,
   585→                latest_valid_hash: Some(forkchoice_state.head_block_hash),
   586→                validation_error: None,
   587→            },
   588→            payload_id: id.map(Into::into),
   589→        })
   590→    }
