   865→pub fn generate_genesis_header<E: EthSpec>(
   866→    spec: &ChainSpec,
   867→    post_transition_merge: bool,
   868→) -> Option<ExecutionPayloadHeader<E>> {
   869→    let genesis_fork = spec.fork_name_at_slot::<E>(spec.genesis_slot);
   870→    let genesis_block_hash =
   871→        generate_genesis_block(spec.terminal_total_difficulty, DEFAULT_TERMINAL_BLOCK)
   872→            .ok()
   873→            .map(|block| block.block_hash);
   874→    let empty_transactions_root = Transactions::<E>::empty().tree_hash_root();
   875→    match genesis_fork {
   876→        ForkName::Base | ForkName::Altair => None,
   877→        ForkName::Bellatrix => {
   878→            if post_transition_merge {
   879→                let mut header = ExecutionPayloadHeader::Bellatrix(<_>::default());
   880→                *header.block_hash_mut() = genesis_block_hash.unwrap_or_default();
   881→                *header.transactions_root_mut() = empty_transactions_root;
   882→                Some(header)
   883→            } else {
   884→                Some(ExecutionPayloadHeader::<E>::Bellatrix(<_>::default()))
   885→            }
   886→        }
   887→        ForkName::Capella => {
   888→            let mut header = ExecutionPayloadHeader::Capella(<_>::default());
   889→            *header.block_hash_mut() = genesis_block_hash.unwrap_or_default();
   890→            *header.transactions_root_mut() = empty_transactions_root;
   891→            Some(header)
   892→        }
   893→        ForkName::Deneb => {
   894→            let mut header = ExecutionPayloadHeader::Deneb(<_>::default());
   895→            *header.block_hash_mut() = genesis_block_hash.unwrap_or_default();
   896→            *header.transactions_root_mut() = empty_transactions_root;
   897→            Some(header)
   898→        }
   899→        ForkName::Electra => {
   900→            let mut header = ExecutionPayloadHeader::Electra(<_>::default());
   901→            *header.block_hash_mut() = genesis_block_hash.unwrap_or_default();
   902→            *header.transactions_root_mut() = empty_transactions_root;
   903→            Some(header)
   904→        }
   905→        ForkName::Fulu => {
   906→            let mut header = ExecutionPayloadHeader::Fulu(<_>::default());
   907→            *header.block_hash_mut() = genesis_block_hash.unwrap_or_default();
   908→            *header.transactions_root_mut() = empty_transactions_root;
   909→            Some(header)
   910→        }
   911→        ForkName::Gloas => {
   912→            let mut header = ExecutionPayloadHeader::Gloas(<_>::default());
   913→            *header.block_hash_mut() = genesis_block_hash.unwrap_or_default();
   914→            *header.transactions_root_mut() = empty_transactions_root;
   915→            Some(header)
   916→        }
   917→    }
   918→}
